/** Builds labyrinths for the tests. Room i is called "R" + i. */
class Lab {
    static Room[] build(int[] ages, int[][] doors) {
        Room[] r = new Room[ages.length];
        for (int i = 0; i < r.length; i++) {
            r[i] = new Room();
            r[i].name = "R" + i;
            r[i].age = ages[i];
        }
        for (int i = 0; i < r.length; i++) {
            r[i].doorsTo = new Room[doors[i].length];
            for (int j = 0; j < doors[i].length; j++) r[i].doorsTo[j] = r[doors[i][j]];
        }
        return r;
    }

    /** k diamonds in a row: 2^k paths from R0 to the last room. */
    static Room[] diamonds(int k) {
        int n = 3 * k + 1;
        int[] ages = new int[n];
        int[][] doors = new int[n][];
        for (int i = 0; i < k; i++) {
            int top = 3 * i;
            ages[top] = 1; ages[top + 1] = 2; ages[top + 2] = 2;
            doors[top] = new int[]{top + 1, top + 2};
            doors[top + 1] = new int[]{top + 3};
            doors[top + 2] = new int[]{top + 3};
        }
        ages[n - 1] = 1;
        doors[n - 1] = new int[0];
        return build(ages, doors);
    }

    /** diamonds(k) plus one more room y at the end of the array; if doorToY, R0 also has a door straight to y. */
    static Room[] diamondsAndY(int k, boolean doorToY) {
        Room[] d = diamonds(k);
        Room[] r = java.util.Arrays.copyOf(d, d.length + 1);
        Room y = new Room();
        y.name = "R" + d.length;
        y.age = 5;
        y.doorsTo = new Room[0];
        r[d.length] = y;
        if (doorToY) r[0].doorsTo = new Room[]{r[0].doorsTo[0], r[0].doorsTo[1], y};
        return r;
    }
}

