        }
        if (i == ages.length - 1) {
            if (room.isExit()) {
                System.out.println(path);   // bonus
                return true;
            }
            return false;
        }
        for (Room next : room.doorsTo) {
            if (hasPathWithAges(next, ages, i + 1, path + " " + next.name)) {
                return true;
            }
        }
        return false;
    }

    // Exercise 5 (Task 2): walk two paths r and s at the same time, like Exercise 4
    // (s plays the role of ages). diverged = the paths differed at some position.
    public static boolean task2(Room room) {
        return task2(room, room, false);
    }

    static boolean task2(Room r, Room s, boolean diverged) {
        if (r.age != s.age) {
            return false;
        }
        if (r.isExit() && s.isExit()) {
            return diverged;
        }
        for (Room nextR : r.doorsTo) {
            for (Room nextS : s.doorsTo) {
                if (task2(nextR, nextS, diverged || nextR != nextS)) {
                    return true;
                }
            }
        }
        return false;
    }

    // Exercise 6: we don't need all paths, only "0, 1 or more than 1".
    // Stopping at 2 alone is not enough: if y is reachable only once (or not at all),
    // we would still try every path, also the 2^60 ones that never reach y.
    // So remember the answer for each room (memoization): every room is solved once.
    public static boolean uniquePath(Room x, Room y) {
        return pathsUpTo2(x, y, new HashMap<>()) == 1;
    }

    /** Number of paths from x to y: 0, 1 or 2 (2 means "2 or more"). */
    static int pathsUpTo2(Room x, Room y, HashMap<Room, Integer> known) {
        if (x == y) {
            return 1;   // no cycles, so the path can't leave y and come back
        }
        if (known.containsKey(x)) {
            return known.get(x);
        }
        int count = 0;
        for (Room next : x.doorsTo) {
            count = Math.min(2, count + pathsUpTo2(next, y, known));
        }
        known.put(x, count);
        return count;
    }

    // Exercise 7: same idea, but the path ends at any exit instead of at y.
    // Here stopping at 2 is already fast: every room leads to an exit, so there are
    // no dead ends. Each room we enter gives at least one path, so after at most two
    // doors we are done. Memoization like in Exercise 6 works too.
    public static boolean uniqueExitPath(Room x) {
        return exitPathsUpTo2(x) == 1;
    }

    static int exitPathsUpTo2(Room x) {
        if (x.isExit()) {
            return 1;
        }
        int count = 0;
        for (Room next : x.doorsTo) {
            count += exitPathsUpTo2(next);
            if (count >= 2) {
                return 2;
            }
        }
        return count;
    }

    // Exercise 8: the number of paths can be 2^70, so we count modulo MOD.
    // Paths merge, so the same room is reached many times: remember each result
    // (memoization). Without cycles, the count of a room never depends on itself.
    public static long countPaths(Room x, Room y) {
        return countPaths(x, y, new HashMap<>());
    }

    static long countPaths(Room x, Room y, HashMap<Room, Long> known) {
        if (x == y) {
            return 1;
        }
        if (known.containsKey(x)) {
            return known.get(x);
        }
        long count = 0;
        for (Room next : x.doorsTo) {
            count = (count + countPaths(next, y, known)) % MOD;
        }
        known.put(x, count);
        return count;
    }

    public static long countExitPaths(Room x) {
        return countExitPaths(x, new HashMap<>());
    }

    static long countExitPaths(Room x, HashMap<Room, Long> known) {
        if (x.isExit()) {
            return 1;
        }
        if (known.containsKey(x)) {
            return known.get(x);
        }
        long count = 0;
        for (Room next : x.doorsTo) {
            count = (count + countExitPaths(next, known)) % MOD;
        }
        known.put(x, count);
        return count;
    }
}

public class Room {
    public String name;
    public int age;
    public Room[] doorsTo;

    public boolean isExit() {
        return doorsTo.length == 0;
    }

    // added for Exercise 2
    public boolean visited;
}
